# Existing Python + PyYAML only; reads the pinned inputs, writes nothing.
import collections, fnmatch, hashlib, json, zipfile, yaml
def recalculate(archive_path, baseline_path, owners_path, workers_path):
    with zipfile.ZipFile(archive_path) as z:
        scan = json.loads(z.read("evidence/architecture-green/arch-scan.stdout.log"))
    with open(baseline_path, encoding="utf-8") as f: baseline = yaml.safe_load(f)
    with open(owners_path, encoding="utf-8") as f: owners = yaml.safe_load(f)
    with open(workers_path, encoding="utf-8") as f: workers = yaml.safe_load(f)
    assert workers["entries"] == []
    B = {x["fingerprint"]: x for x in baseline["entries"]}
    V = {x["fingerprint"]: x for x in scan["violations"]}
    sets = {}
    sets["new"] = {k: v for k, v in V.items() if k not in B}
    sets["stale"] = {k: v for k, v in B.items() if k not in V}
    sets["grown"] = {k: v for k, v in V.items() if k in B and B[k].get("max_metric") is not None and v.get("metric", 0) > B[k]["max_metric"]}
    sets["workers_in_new"] = {k: v for k, v in sets["new"].items() if v["kind"] == "worker"}
    def owner(v):
        for rule in owners["rules"]:
            if any(fnmatch.fnmatchcase(v["location"]["path"], g) for g in rule["globs"]): return rule["owner"]
        return "NO_CURRENT_OWNER_RULE"
    def count(records, key): return dict(sorted(collections.Counter(key(v) for v in records.values()).items()))
    return {name: {"count": len(records), "fingerprint_set_sha256": hashlib.sha256(("\n".join(sorted(records)) + "\n").encode()).hexdigest(), "by_rule": count(records, lambda v: v["kind"]), "by_owner": count(records, owner), "by_path": count(records, lambda v: v["location"]["path"])} for name, records in sets.items()}
